python3 - <<'PYEOF'
p = '/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature/src/types/checker/inference/expr/effects.rs'
s = open(p).read()
s = s.replace(
    "            if std::env::var(\"ELEPHC_DBG_BYREF\").is_ok() {\n                eprintln!(\"DBG byref {} current={:?} param={:?}\", variable, current, param_ty);\n            }\n",
    "",
)
s = s.replace(
    "            if matches!(current, PhpType::Void) && matches!(param_ty, PhpType::Union(_)) {",
    "            if matches!(current, PhpType::Void) && matches!(param_ty, PhpType::Mixed) {",
)
open(p, 'w').write(s)

p = '/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature/src/ir_lower/expr/call_arg_coercion.rs'
s = open(p).read()
s = s.replace(
    """    let (_, param_ty) = sig.params.get(index)?;
    if !matches!(param_ty, PhpType::Union(_)) {
        return None;
    }
    let ExprKind::Variable(name) = &arg.kind else {
        return None;
    };
    if !matches!(ctx.local_type(name), PhpType::Void) {
        return None;
    }
    let local = ctx.load_local(name, Some(arg.span));
    ctx.store_call_normalized_local(name, local, param_ty.clone(), Some(arg.span));
    Some(ctx.load_local(name, Some(arg.span)).value)""",
    """    let (_, param_ty) = sig.params.get(index)?;
    if !matches!(param_ty, PhpType::Mixed) {
        return None;
    }
    let ExprKind::Variable(name) = &arg.kind else {
        return None;
    };
    if !matches!(ctx.local_type(name), PhpType::Void) {
        return None;
    }
    let local = ctx.load_local(name, Some(arg.span));
    // The slot really is converted, not merely re-typed: the callee writes a boxed value through
    // the pointer, so what the caller hands over has to already be a Mixed cell. This mirrors the
    // `ArrayToMixed` the by-reference array path emits for the same reason.
    let boxed = ctx.emit_value(
        Op::MixedBox,
        vec![local.value],
        None,
        PhpType::Mixed,
        Op::MixedBox.default_effects(),
        Some(arg.span),
    );
    ctx.store_call_normalized_local(name, boxed, PhpType::Mixed, Some(arg.span));
    Some(ctx.load_local(name, Some(arg.span)).value)""",
)
open(p, 'w').write(s)
print("patched")
PYEOF
cargo build 2>&1 | grep -E "^(error|warning)" -A8 | head -25; echo "BUILD_DONE": patched BUILD_DONE
